CREATE OR REPLACE FUNCTION public.acknowledge_material_read(p_lesson_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid();
begin
 if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(v_user::text,0));
 if not public.phase1_lesson_is_available(p_lesson_id,v_user) or exists(select 1 from public.assessment_sessions where user_id=v_user and status='IN_PROGRESS') then
 raise exception 'Material unavailable' using errcode='42501'; end if;
 insert into public.lesson_progress(user_id,lesson_id,status,read_at) values(v_user,p_lesson_id,'IN_PROGRESS',now())
 on conflict(user_id,lesson_id) do update set read_at=coalesce(public.lesson_progress.read_at,now());
end;
$function$

CREATE OR REPLACE FUNCTION public.current_user_has_active_assessment()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_active boolean := false;
begin
  if auth.uid() is null or to_regclass('public.assessment_sessions') is null then return false; end if;
  execute 'select exists (select 1 from public.assessment_sessions where user_id = $1 and status = ''IN_PROGRESS'')'
    into v_active using auth.uid();
  return coalesce(v_active, false);
end;
$function$

CREATE OR REPLACE FUNCTION public.forum_check_writer(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if (select auth.jwt()->>'role') is distinct from 'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
 if p_user_id is null or not exists(select 1 from public.profiles where id=p_user_id) then raise exception 'Forbidden' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
 if exists(select 1 from public.assessment_sessions where user_id=p_user_id and status='IN_PROGRESS') then raise exception 'Assessment active' using errcode='42501'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.forum_moderate(p_user_id uuid, p_target_id uuid, p_action text, p_value boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform public.forum_check_writer(p_user_id);
 if not exists(select 1 from public.profiles where id=p_user_id and role='ADMIN') then raise exception 'Forbidden' using errcode='42501'; end if;
 if p_action='lock_topic' then update public.forum_topics set is_locked=p_value where id=p_target_id;
 elsif p_action='hide_topic' then update public.forum_topics set is_hidden=p_value where id=p_target_id;
 elsif p_action='hide_reply' then update public.forum_replies set is_hidden=p_value where id=p_target_id;
 else raise exception 'Invalid moderation action' using errcode='22023'; end if;
 if not found then raise exception 'Content unavailable' using errcode='22023'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.start_assessment_session(p_assessment_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid := auth.uid(); v_test public.assessments%rowtype; v_id uuid; v_active_assessment uuid;
begin
 if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
 -- Serialize starts and reading acknowledgement for the same learner.
 perform pg_advisory_xact_lock(hashtextextended(v_user::text,0));
 select a.* into v_test from public.assessments a join public.learning_paths p on p.id=a.learning_path_id
 where a.id=p_assessment_id and a.is_published and p.is_published;
 if not found then raise exception 'Assessment unavailable' using errcode='42501'; end if;
 select id,assessment_id into v_id,v_active_assessment from public.assessment_sessions where user_id=v_user and status='IN_PROGRESS' order by started_at limit 1;
 if v_id is not null then
  if v_active_assessment=p_assessment_id then return v_id; end if;
  raise exception 'Finish the active assessment first' using errcode='42501';
 end if;
 if v_test.type='PRETEST' then raise exception 'Assessment retired' using errcode='42501'; end if;
  if exists(select 1 from public.lessons l join public.chapters c on c.id=l.chapter_id
   where c.learning_path_id=v_test.learning_path_id and c.is_published and c.is_required and l.is_published and l.is_required
    and c.position<=v_test.gate_after_chapter
    and not exists(select 1 from public.lesson_progress lp where lp.user_id=v_user and lp.lesson_id=l.id and lp.status='COMPLETED')) then
   raise exception 'Required material incomplete' using errcode='42501'; end if;
 if not exists(select 1 from public.assessment_items where assessment_id=v_test.id) then raise exception 'No assessment items'; end if;
 insert into public.assessment_sessions(user_id,assessment_id) values(v_user,p_assessment_id) returning id into v_id;
 return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_code_request_quota(p_kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_window timestamptz := date_trunc('minute', now());
  v_limit integer;
  v_accepted boolean := false;
begin
  if v_user_id is null or p_kind not in ('check', 'ai', 'assessment') then return false; end if;
  v_limit := case when p_kind = 'assessment' then 4 else 8 end;
  insert into public.code_request_limits as quota (user_id, kind, window_started_at, request_count)
  values (v_user_id, p_kind, v_window, 1)
  on conflict (user_id, kind) do update
  set window_started_at = v_window,
      request_count = case when quota.window_started_at = v_window then quota.request_count + 1 else 1 end
  where quota.window_started_at <> v_window or quota.request_count < v_limit
  returning true into v_accepted;
  return coalesce(v_accepted, false);
end;
$function$

CREATE OR REPLACE FUNCTION public.phase1_start_lesson(p_lesson_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user_id uuid := auth.uid();
begin
  if v_user_id is null or not public.phase1_lesson_is_available(p_lesson_id, v_user_id) then
    raise exception 'Lesson unavailable' using errcode = '42501';
  end if;
  insert into public.lesson_progress (user_id, lesson_id, status)
  values (v_user_id, p_lesson_id, 'IN_PROGRESS')
  on conflict (user_id, lesson_id) do nothing;
end;
$function$
